def canonical_gtin(value):
    if not value.isascii() or not value.isdigit() or len(value) not in (8, 12, 13, 14):
        return None
    digits = list(map(int, value))
    check = (10 - sum(d * (3 if i % 2 == 0 else 1) for i, d in enumerate(reversed(digits[:-1]))) % 10) % 10
    return value.zfill(14) if digits[-1] == check else None


